#include <stdbool.h>

/* arr must be sorted ascending */
bool pair_sum(const int arr[], int n, int target) {
  int lo = 0, hi = n - 1;
  while (lo < hi) {
    long s = (long)arr[lo] + arr[hi];
    if (s == target) return true;
    if (s < target) lo++;          /* need a bigger sum */
    else hi--;                     /* need a smaller sum */
  }
  return false;
}

/* remove duplicates from a sorted array in place, return the new length */
int dedupe(int a[], int n) {
  if (n == 0) return 0;
  int w = 1;                      /* write index */
  for (int r = 1; r < n; r++)     /* read index */
    if (a[r] != a[w - 1]) a[w++] = a[r];
  return w;
}

/* length of the shortest subarray with sum >= k (all values positive), or 0 */
int min_len(const int a[], int n, long k) {
  int best = n + 1, left = 0;
  long sum = 0;
  for (int right = 0; right < n; right++) {
    sum += a[right];                    /* grow the window */
    while (sum >= k) {                  /* shrink while still valid */
      if (right - left + 1 < best) best = right - left + 1;
      sum -= a[left++];
    }
  }
  return best == n + 1 ? 0 : best;
}

/* all unique triplets with a + b + c == 0; a must be sorted. prints each one */
void three_sum(int a[], int n) {
  for (int i = 0; i + 2 < n && a[i] <= 0; i++) {
    if (i > 0 && a[i] == a[i - 1]) continue;        /* skip duplicate anchors */
    int lo = i + 1, hi = n - 1;
    while (lo < hi) {
      int s = a[i] + a[lo] + a[hi];
      if (s < 0) lo++;
      else if (s > 0) hi--;
      else {
        printf("%d %d %d\n", a[i], a[lo], a[hi]);
        lo++; hi--;
        while (lo < hi && a[lo] == a[lo - 1]) lo++;   /* skip duplicates */
        while (lo < hi && a[hi] == a[hi + 1]) hi--;
      }
    }
  }
}

int max_area(const int h[], int n) {
  int lo = 0, hi = n - 1, best = 0;
  while (lo < hi) {
    int width = hi - lo, height = h[lo] < h[hi] ? h[lo] : h[hi];
    if (width * height > best) best = width * height;
    if (h[lo] < h[hi]) lo++; else hi--;      /* move the shorter wall */
  }
  return best;
}

typedef struct Node { int val; struct Node *next; } Node;

Node *cycle_start(Node *head) {
  Node *slow = head, *fast = head;
  while (fast && fast->next) {
    slow = slow->next;
    fast = fast->next->next;
    if (slow == fast) {                 /* they met inside the cycle */
      slow = head;                      /* restart one pointer at the head */
      while (slow != fast) { slow = slow->next; fast = fast->next; }
      return slow;                      /* both now at the cycle entry */
    }
  }
  return NULL;                         /* no cycle */
}

/* longest substring without repeating characters (ASCII) */
int longest_unique(const char *s) {
  int last[256], best = 0, left = 0;
  for (int i = 0; i < 256; i++) last[i] = -1;
  for (int right = 0; s[right]; right++) {
    unsigned char c = (unsigned char)s[right];
    if (last[c] >= left) left = last[c] + 1;      /* jump past the previous copy */
    last[c] = right;
    if (right - left + 1 > best) best = right - left + 1;
  }
  return best;
}
